def f(inp):
    H,W=len(inp),len(inp[0])
    from collections import Counter
    cnt=Counter(x for r in inp for x in r)
    bg=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=bg]
    obst=max(others,key=lambda c:cnt[c])
    mark=[c for c in others if c!=obst][0]
    seg=sorted((i,j) for i in range(H) for j in range(W) if inp[i][j]==mark)
    out=[r[:] for r in inp]
    def set3(p):
        if inp[p[0]][p[1]]==bg: out[p[0]][p[1]]=3
    for s,e in ((seg[0],seg[-1]),(seg[-1],seg[0])):
        dd=(e[0]-s[0], e[1]-s[1]); dd=(dd[0]>0-(dd[0]<0), dd[1]>0-(dd[1]<0))
        d=dd if s==seg[-1] else (-dd[0],-dd[1])
        p=s
        while True:
            q=(p[0]+d[0], p[1]+d[1])
            if not(0<=q[0]<H and 0<=q[1]<W): break
            v=inp[q[0]][q[1]]
            if v==mark: break
            if v==obst:
                right = q[1]+1<W and inp[q[0]][q[1]+1]==obst
                left  = q[1]-1>=0 and inp[q[0]][q[1]-1]==obst
                top   = q[0]-1>=0 and inp[q[0]-1][q[1]]==obst
                bottom=q[0]+1<H and inp[q[0]+1][q[1]]==obst
                if right: p=(q[0],q[1]-1); d=(d[0],-d[1])
                elif left:  p=(q[0],q[1]+1); d=(d[0],-d[1])
                elif bottom:p=(q[0],q[1]); d=(-d[0],d[1])
                else:       p=(q[0],q[1]); d=(-d[0],d[1])
                continue
            p=q; set3(p)
    return out
